#include <iostream>
using namespace std;

struct ChainNode {
    int data;
    ChainNode *next;
    ChainNode(int d) : data(d), next(0) {}
};

int main() {
    int n;
    if (!(cin >> n)) return 0;

    ChainNode *first = 0, *rear = 0;
    for (int i = 0; i < n; i++) {
        int v;
        cin >> v;
        ChainNode *s = new ChainNode(v);
        if (first == 0) first = rear = s;
        else { rear->next = s; rear = s; }
    }

    int target;
    cin >> target;

    // 用前驱 pre 的视角删除；pre == 0 表示删的是首结点
    ChainNode *pre = 0, *p = first;
    while (p != 0) {
        if (p->data == target) {
            ChainNode *victim = p;
            if (pre == 0) first = p->next;      // 删首结点，要改 first
            else pre->next = p->next;           // 否则改前驱的 next
            p = p->next;
            delete victim;
        } else {
            pre = p;
            p = p->next;
        }
    }

    if (first == 0) {
        cout << "empty\n";
        return 0;
    }
    for (ChainNode *q = first; q != 0; q = q->next)
        cout << q->data << (q->next == 0 ? '\n' : ' ');
    return 0;
}
